  "tags": "Nhóm món: Trứng & đậu · Độ cay: Nhẹ",
  "intro": "",
  "ingredients": [
   {
    "name": "Nguyên liệu chính",
    "items": [
     "10 quả trứng cút, luộc chín, bóc vỏ",
     "¼ củ hành tây, cắt múi cau",
     "4 tai nấm mèo ngâm, cắt miếng",
     "¼ trái ớt chuông đỏ, cắt miếng",
     "100 g bắp non, cắt xéo",
     "1 trái cà chua, cắt hạt lựu",
     "Bột chiên giòn (để lăn trứng và bắp; nguồn dùng bột tẩm khô chiên giòn đóng gói)",
     "Dầu ăn"
    ]
   },
   {
    "name": "Sốt chua ngọt",
    "items": [
     "1 muỗng canh đường",
     "2 muỗng canh giấm gạo",
     "1 muỗng canh tương ớt",
     "½ muỗng canh dầu hào",
     "½ muỗng canh hạt nêm",
     "½ chén nước"
    ]
   },
   {
    "name": "Rau nêm",
    "items": [
     "1 muỗng canh hành tím cắt lát (để phi)",
     "Hành lá, rau răm (cắt khúc), tiêu"
    ]
   }
  ],
  "steps": [
   {
    "title": "Chiên trứng",
    "text": "Đun nóng dầu. Lăn trứng cút và bắp non qua bột chiên giòn, chiên vàng rồi vớt ra để ráo.",
    "subs": [],
    "after": "",
    "minutes": null
   },
   {
    "title": "Pha sốt",
    "text": "Khuấy tan **1 muỗng canh đường**, **2 muỗng canh giấm gạo**, **1 muỗng canh tương ớt**, **½ muỗng canh dầu hào**, **½ muỗng canh hạt nêm** và **½ chén nước**.",
    "subs": [],
    "after": "",
    "minutes": null
   },
   {
    "title": "Xào rau",
    "text": "Phi thơm **1 muỗng canh hành tím**. Cho cà chua, nấm mèo, ớt chuông vào xào mềm, rồi thêm bắp non và hành tây.",
    "subs": [],
    "after": "",
    "minutes": null
   },
   {
    "title": "Hoàn thành",
    "text": "Cho trứng cút và sốt vào, xào đến khi rau củ vừa chín. Thêm hành lá, rau răm rồi tắt lửa.",
    "subs": [],
    "after": "",
    "minutes": null
   },
   {
    "title": "Dùng",
    "text": "Rắc tiêu, ăn nóng với cơm.",
    "subs": [],
    "after": "",
    "minutes": null
   }
  ],
  "tips": [],
